 provenance constant jsonb := $provenance$[{"id":"27b5b2a7-71c3-4334-9b15-6087aeab8cf0","receive":"c752eacf-82b9-4496-a37a-400000000283","sale":"73bc46bf-13c0-4e6f-a6b2-300000000000","receive_reference":"GRN-STR1-202610-0002","sale_reference":"STR1-WIN51-20261105-0002","po":"c752eacf-82b9-4496-837a-a84271154ffe","po_item":"091f3a5b-71bb-45c3-951e-80237f3e147d","sale_id":"73bc46bf-13c0-4e6f-a6b2-e4511b16cfa9","sale_item":"73bc46bf-13c0-4e6f-a6b2-100000000000"},{"id":"29da1541-a922-40f9-aaf5-b336b24107a8","receive":"c752eacf-82b9-4496-a37a-400000000138","sale":"82ee0bfe-d986-4215-a4a4-300000000001","receive_reference":"GRN-STR1-202610-0002","sale_reference":"STR1-WIN51-20261105-0004","po":"c752eacf-82b9-4496-837a-a84271154ffe","po_item":"1e0459d5-adb4-4819-8a0f-436045462373","sale_id":"82ee0bfe-d986-4215-84a4-f83bc9d79d15","sale_item":"82ee0bfe-d986-4215-a4a4-100000000001"},{"id":"9ffab37c-7d1e-425b-b4b1-bf887be41714","receive":"c752eacf-82b9-4496-a37a-400000000393","sale":"82ee0bfe-d986-4215-a4a4-300000000000","receive_reference":"GRN-STR1-202610-0002","sale_reference":"STR1-WIN51-20261105-0004","po":"c752eacf-82b9-4496-837a-a84271154ffe","po_item":"05736820-04cd-4ed3-b060-b8b33de920fc","sale_id":"82ee0bfe-d986-4215-84a4-f83bc9d79d15","sale_item":"82ee0bfe-d986-4215-a4a4-100000000000"}]$provenance$;
 branch constant text := 'a611a328-2217-4d77-944a-5f6a637d123b';
 repair_key constant text := 'OWNERSHIP3-STR1-20261106';
 receipt_id constant uuid := md5('OWNERSHIP3-STR1-20261106')::uuid;
 before_rows jsonb; after_rows jsonb; receipt public.audit_logs%ROWTYPE;
 item jsonb; expected jsonb; actual jsonb; before_row jsonb; after_row jsonb;
 n integer; changed integer; feed_start bigint; replay boolean:=false; stamp timestamptz:=transaction_timestamp();
BEGIN
 IF current_user<>'postgres' OR current_database()<>'postgres' OR auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'OWNERSHIP3_WRONG_EXECUTION_IDENTITY';END IF;
 IF jsonb_array_length(manifest)<>3 OR (SELECT count(DISTINCT value->>'id') FROM jsonb_array_elements(manifest))<>3 THEN RAISE EXCEPTION 'OWNERSHIP3_INVALID_MANIFEST';END IF;
 -- A single receipt serializes first execution and replay, including an absent row.
 IF NOT pg_try_advisory_xact_lock(hashtextextended(repair_key,0)) THEN RAISE EXCEPTION 'OWNERSHIP3_BUSY';END IF;
 PERFORM id FROM public.stores ORDER BY id FOR SHARE NOWAIT;
 IF NOT EXISTS(SELECT 1 FROM public.stores WHERE id=branch AND code='STR1' AND group_id='361-degree-sports' AND is_active AND deleted_at IS NULL) THEN RAISE EXCEPTION 'OWNERSHIP3_BRANCH_CHANGED';END IF;
 PERFORM p.id FROM public.products p JOIN jsonb_array_elements(manifest) m ON p.id=(m->>'id')::uuid ORDER BY p.id FOR UPDATE OF p NOWAIT;
 SELECT * INTO receipt FROM public.audit_logs WHERE id=receipt_id FOR UPDATE NOWAIT;
 replay:=FOUND;
 -- Run the same raw-source/ACL/schema/trigger guards before and after DML.
 FOR n IN 1..2 LOOP
  FOR expected IN SELECT value FROM jsonb_array_elements(metadata->'functions') LOOP
   SELECT jsonb_build_object('signature',expected->>'signature','body_md5',md5(p.prosrc),'owner',pg_get_userbyid(p.proowner),'acl',(SELECT jsonb_agg(x::text ORDER BY x::text) FROM unnest(p.proacl) x),'config',to_jsonb(p.proconfig),'strict',p.proisstrict,'definer',p.prosecdef,'volatility',p.provolatile) INTO actual FROM pg_proc p WHERE p.oid=to_regprocedure(expected->>'signature');
   IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'OWNERSHIP3_ROUTINE_CHANGED: %',expected->>'signature';END IF;
  END LOOP;
  SELECT coalesce(jsonb_agg(jsonb_build_object('table_name',c.relname,'tgname',t.tgname,'tgenabled',t.tgenabled,'trigger_definition',pg_get_triggerdef(t.oid),'signature',CASE WHEN ns.nspname='public' THEN 'public.' ELSE ns.nspname||'.' END||p.proname||'('||pg_get_function_identity_arguments(p.oid)||')') ORDER BY c.relname,t.tgname),'[]') INTO actual FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_proc p ON p.oid=t.tgfoid JOIN pg_namespace ns ON ns.oid=p.pronamespace WHERE t.tgrelid IN ('public.products'::regclass,'public.audit_logs'::regclass,'public.change_history'::regclass,'public.sync_change_feed'::regclass) AND NOT t.tgisinternal;
  SELECT jsonb_agg(value ORDER BY value->>'table_name',value->>'tgname') INTO expected FROM jsonb_array_elements(metadata->'triggers');
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'OWNERSHIP3_TRIGGER_CHANGED';END IF;
  SELECT jsonb_agg(jsonb_build_object('table_name',table_name,'column_name',column_name,'udt_schema',udt_schema,'udt_name',udt_name,'is_nullable',is_nullable,'column_default',column_default,'ordinal_position',ordinal_position) ORDER BY table_name,ordinal_position) INTO actual FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('products','audit_logs','change_history','sync_change_feed','stores','sales','sale_items');
  SELECT jsonb_agg(value ORDER BY value->>'table_name',(value->>'ordinal_position')::integer) INTO expected FROM jsonb_array_elements(metadata->'columns');
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'OWNERSHIP3_SCHEMA_CHANGED';END IF;
  SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid)) ORDER BY c.relname,k.conname) INTO actual FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid WHERE k.contype<>'n' AND k.conrelid IN ('public.products'::regclass,'public.audit_logs'::regclass,'public.change_history'::regclass,'public.sync_change_feed'::regclass,'public.stores'::regclass,'public.sales'::regclass,'public.sale_items'::regclass);
  SELECT jsonb_agg(value ORDER BY value->>'table',value->>'name') INTO expected FROM jsonb_array_elements(metadata->'constraints');
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'OWNERSHIP3_CONSTRAINT_CHANGED';END IF;
  IF n=2 THEN EXIT;END IF;
  SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO after_rows FROM public.products p JOIN jsonb_array_elements(manifest) m ON p.id=(m->>'id')::uuid;
  IF jsonb_array_length(after_rows) IS DISTINCT FROM 3 THEN RAISE EXCEPTION 'OWNERSHIP3_MISSING_PRODUCT';END IF;
  IF replay THEN
   IF receipt.action_category IS DISTINCT FROM 'maintenance' OR receipt.action_name IS DISTINCT FROM 'repair_product_ownership' OR receipt.target_module IS DISTINCT FROM 'inventory' OR receipt.action IS DISTINCT FROM 'repair' OR receipt.entity IS DISTINCT FROM 'products' OR receipt.details->>'execution_identity' IS DISTINCT FROM 'database maintenance / postgres' OR receipt.details->>'product_count' IS DISTINCT FROM '3' OR receipt.store_id IS DISTINCT FROM branch OR receipt.user_id IS NOT NULL OR receipt.user_name IS DISTINCT FROM current_user OR receipt.details->>'repair_key' IS DISTINCT FROM repair_key OR receipt.details->'manifest' IS DISTINCT FROM manifest OR receipt.after_state IS DISTINCT FROM after_rows OR jsonb_typeof(receipt.before_state) IS DISTINCT FROM 'array' OR jsonb_array_length(receipt.before_state)<>3 THEN RAISE EXCEPTION 'OWNERSHIP3_INVALID_REPLAY';END IF;
   before_rows:=receipt.before_state;
  ELSE
   before_rows:=after_rows;
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(manifest) LOOP
   SELECT value INTO before_row FROM jsonb_array_elements(before_rows) WHERE value->>'id'=item->>'id';
   IF before_row IS NULL OR md5(before_row::text) IS DISTINCT FROM item->>'before_md5' OR before_row->'owner_store_id' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'OWNERSHIP3_BEFORE_IMAGE_CHANGED';END IF;
  END LOOP;
  -- Freeze original receiving and accepted sale movements, not device clocks.
  PERFORM a.id FROM public.item_activity_logs a WHERE a.id IN (SELECT (v->>'receive')::uuid FROM jsonb_array_elements(provenance) v UNION ALL SELECT (v->>'sale')::uuid FROM jsonb_array_elements(provenance) v) FOR SHARE NOWAIT;
  PERFORM d.movement_id FROM public.stock_delta_applied d WHERE d.movement_id IN (SELECT (v->>'receive')::uuid FROM jsonb_array_elements(provenance) v UNION ALL SELECT (v->>'sale')::uuid FROM jsonb_array_elements(provenance) v) FOR SHARE NOWAIT;
  PERFORM po.id FROM public.purchase_orders po WHERE po.id IN (SELECT (v->>'po')::uuid FROM jsonb_array_elements(provenance) v) FOR SHARE NOWAIT;
  PERFORM i.id FROM public.purchase_order_items i WHERE i.id IN (SELECT (v->>'po_item')::uuid FROM jsonb_array_elements(provenance) v) FOR SHARE NOWAIT;
  PERFORM s.id FROM public.sales s WHERE s.id IN (SELECT (v->>'sale_id')::uuid FROM jsonb_array_elements(provenance) v) FOR SHARE NOWAIT;
  PERFORM i.id FROM public.sale_items i WHERE i.id IN (SELECT (v->>'sale_item')::uuid FROM jsonb_array_elements(provenance) v) FOR SHARE NOWAIT;
  IF jsonb_array_length(provenance)<>3 OR (SELECT count(DISTINCT v->>'id') FROM jsonb_array_elements(provenance) v)<>3 OR EXISTS(SELECT 1 FROM jsonb_array_elements(provenance) v WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(manifest) m WHERE m->>'id'=v->>'id')) THEN RAISE EXCEPTION 'OWNERSHIP3_SOURCE_MANIFEST_INVALID';END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(provenance) LOOP
   IF NOT EXISTS(SELECT 1 FROM public.item_activity_logs r JOIN public.item_activity_logs s ON s.id=(item->>'sale')::uuid
     JOIN public.stock_delta_applied rd ON rd.movement_id=r.id JOIN public.stock_delta_applied sd ON sd.movement_id=s.id
     JOIN public.purchase_orders po ON po.id=(item->>'po')::uuid JOIN public.purchase_order_items pi ON pi.id=(item->>'po_item')::uuid AND pi.po_id=po.id
     JOIN public.sales sale ON sale.id=(item->>'sale_id')::uuid JOIN public.sale_items si ON si.id=(item->>'sale_item')::uuid AND si.sale_id=sale.id
     WHERE r.id=(item->>'receive')::uuid AND r.product_id=(item->>'id')::uuid AND s.product_id=r.product_id AND rd.product_id=r.product_id AND sd.product_id=r.product_id AND pi.product_id=r.product_id AND si.product_id=r.product_id
       AND r.store_id=branch AND s.store_id=branch AND rd.store_id=branch AND sd.store_id=branch AND po.store_id=branch AND sale.store_id=branch
       AND r.activity_type='receive' AND s.activity_type='sale' AND r.reference=item->>'receive_reference' AND s.reference=item->>'sale_reference' AND po.reference=r.reference AND sale.bill_number=s.reference
       AND r.quantity_delta=1 AND s.quantity_delta=-1 AND rd.delta=1 AND sd.delta=-1 AND pi.quantity_received=1 AND po.status='posted' AND si.quantity=1 AND NOT coalesce(si.is_return,false) AND coalesce(si.refunded_qty,0)=0 AND NOT coalesce(sale.is_refunded,false)) THEN RAISE EXCEPTION 'OWNERSHIP3_SOURCE_PROOF_CHANGED';END IF;
  END LOOP;
  IF (SELECT count(*) FROM public.item_activity_logs a WHERE a.product_id IN (SELECT (v->>'id')::uuid FROM jsonb_array_elements(manifest) v))<>6 OR
     (SELECT count(*) FROM public.stock_delta_applied d WHERE d.product_id IN (SELECT (v->>'id')::uuid FROM jsonb_array_elements(manifest) v))<>6 THEN RAISE EXCEPTION 'OWNERSHIP3_SOURCE_PROOF_CHANGED';END IF;
  IF EXISTS(SELECT 1 FROM public.purchase_order_items i JOIN public.purchase_orders po ON po.id=i.po_id WHERE i.product_id IN (SELECT (v->>'id')::uuid FROM jsonb_array_elements(manifest) v) AND po.store_id IS DISTINCT FROM branch) THEN RAISE EXCEPTION 'OWNERSHIP3_COMPETING_RECEIVING';END IF;
  -- Revalidate provenance instead of assigning products solely from stock state.
  IF EXISTS(SELECT 1 FROM public.products p JOIN jsonb_array_elements(manifest) m ON p.id=(m->>'id')::uuid WHERE p.stock_quantity IS DISTINCT FROM 0 OR p.stock_by_store IS DISTINCT FROM jsonb_build_object(branch,0) OR p.stock_by_store IS DISTINCT FROM public.canonical_stock_by_store(p.stock_by_store) OR p.catalogue_store_ids IS DISTINCT FROM public.received_product_catalogue_stores(p.id) OR p.deleted_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.sale_items i JOIN public.sales s ON s.id=i.sale_id WHERE i.product_id=p.id AND s.store_id=branch) OR EXISTS(SELECT 1 FROM public.sale_items i JOIN public.sales s ON s.id=i.sale_id WHERE i.product_id=p.id AND s.store_id IS DISTINCT FROM branch)) THEN RAISE EXCEPTION 'OWNERSHIP3_PROVENANCE_CHANGED';END IF;
  IF NOT replay THEN
   SELECT coalesce(max(cursor),0) INTO feed_start FROM public.sync_change_feed;
   PERFORM set_config('pos.source_application',repair_key,true);
   PERFORM set_config('pos.updated_by','',true);PERFORM set_config('pos.device_id','',true);PERFORM set_config('pos.sync_terminal','',true);
   UPDATE public.products p SET owner_store_id=branch FROM jsonb_array_elements(manifest) m WHERE p.id=(m->>'id')::uuid AND p.owner_store_id IS NULL;
   GET DIAGNOSTICS changed=ROW_COUNT;
   IF changed<>3 THEN RAISE EXCEPTION 'OWNERSHIP3_UPDATE_CARDINALITY';END IF;
   SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) INTO after_rows FROM public.products p JOIN jsonb_array_elements(manifest) m ON p.id=(m->>'id')::uuid;
  END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(manifest) LOOP
   SELECT value INTO before_row FROM jsonb_array_elements(before_rows) WHERE value->>'id'=item->>'id';
   SELECT value INTO after_row FROM jsonb_array_elements(after_rows) WHERE value->>'id'=item->>'id';
   IF after_row->>'owner_store_id' IS DISTINCT FROM branch OR (after_row-'owner_store_id'-'row_version'-'updated_at') IS DISTINCT FROM (before_row-'owner_store_id'-'row_version'-'updated_at') OR (after_row->>'row_version')::bigint IS DISTINCT FROM (before_row->>'row_version')::bigint+1 OR ((after_row->>'updated_at')::timestamptz IS DISTINCT FROM CASE WHEN replay THEN receipt.created_at ELSE stamp END) OR NOT public.product_available_in_catalogue((item->>'id')::uuid,branch) THEN RAISE EXCEPTION 'OWNERSHIP3_UNEXPECTED_PRODUCT_CHANGE';END IF;
   IF (SELECT count(*) FROM public.change_history h WHERE h.entity_type='products' AND h.entity_id=item->>'id' AND h.revision=(after_row->>'row_version')::bigint AND h.action='update' AND h.old_value=before_row-'stock_by_store'-'stock_quantity' AND h.new_value=after_row-'stock_by_store'-'stock_quantity' AND h.source_application=repair_key AND h.scope_type='BRANCH' AND h.scope_id=branch AND h.changed_by IS NULL AND h.device_id IS NULL AND h.terminal_id IS NULL)<>1 THEN RAISE EXCEPTION 'OWNERSHIP3_HISTORY_MISSING';END IF;
   IF (SELECT count(*) FROM public.sync_change_feed f WHERE f.organization_id='default' AND f.branch_id='global' AND f.terminal_id IS NULL AND f.table_name='products' AND f.entity_id=jsonb_build_object('id',item->>'id')::text AND f.operation='update' AND NOT f.tombstone AND f.row_version=(after_row->>'row_version')::bigint)<>1 THEN RAISE EXCEPTION 'OWNERSHIP3_PRODUCT_FEED_MISSING';END IF;
  END LOOP;
  IF NOT replay THEN
   INSERT INTO public.audit_logs(id,user_name,user_id,action_category,action_name,target_module,details,store_id,action,entity,before_state,after_state)
   VALUES(receipt_id,current_user,NULL,'maintenance','repair_product_ownership','inventory',jsonb_build_object('repair_key',repair_key,'manifest',manifest,'execution_identity','database maintenance / postgres','product_count',3),branch,'repair','products',before_rows,after_rows);
   IF (SELECT count(*) FROM public.sync_change_feed WHERE cursor>feed_start AND ((table_name='products' AND entity_id IN (SELECT jsonb_build_object('id',value->>'id')::text FROM jsonb_array_elements(manifest))) OR (table_name='audit_logs' AND entity_id=jsonb_build_object('id',receipt_id)::text)))<>4 THEN RAISE EXCEPTION 'OWNERSHIP3_FEED_CARDINALITY';END IF;
  END IF;
  IF (SELECT count(*) FROM public.sync_change_feed WHERE table_name='audit_logs' AND entity_id=jsonb_build_object('id',receipt_id)::text AND branch_id=branch AND terminal_id IS NULL AND operation='insert' AND NOT tombstone AND row_version=1)<>1 THEN RAISE EXCEPTION 'OWNERSHIP3_AUDIT_FEED_MISSING';END IF;
 END LOOP;
 RAISE NOTICE 'OWNERSHIP3 verified %, products3 / history3 / feed4 / receipt1',CASE WHEN replay THEN 'existing repair' ELSE 'new repair' END;
END;
$repair$;
COMMIT;
